 @Test public void twoThousandEntryLocalMutationPassesDirectAndBackupValidation()throws Exception{long started=System.nanoTime();activity.mutate(()->{android.database.sqlite.SQLiteStatement insert=activity.db.compileStatement("INSERT INTO tx(uuid,kind,amount,day,account,dest,category,note,person,loan) VALUES(?,'expense',100,'2026-11-11','Cash','','Food','','','')");try{for(int n=0;n<2000;n++){insert.bindString(1,java.util.UUID.randomUUID().toString());insert.executeInsert();}}finally{insert.close();}});long elapsed=(System.nanoTime()-started)/1000000;assertEquals(2000,activity.sum("SELECT count(*) FROM tx"));activity.validate(new org.json.JSONObject(new String(activity.data(),java.nio.charset.StandardCharsets.UTF_8)));System.out.println("Simulation only: atomic 2000-row insert plus direct validation "+elapsed+"ms. Not a device performance benchmark.");}
