 int countTransactionRows(View view){int count="hisab-transaction-amount".equals(view.getTag())?1:0;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)count+=countTransactionRows(((ViewGroup)view).getChildAt(i));return count;}
 TextView findText(View view,String expected){if(view instanceof TextView&&expected.contentEquals(((TextView)view).getText()))return(TextView)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){TextView found=findText(((ViewGroup)view).getChildAt(i),expected);if(found!=null)return found;}return null;}
 LedgerChart findChart(View view,boolean donut){if(view instanceof LedgerChart&&((LedgerChart)view).donut==donut)return(LedgerChart)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){LedgerChart found=findChart(((ViewGroup)view).getChildAt(i),donut);if(found!=null)return found;}return null;}
 String allText(View v){StringBuilder s=new StringBuilder();if(v instanceof TextView)s.append(((TextView)v).getText()).append("\n");if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s.append(allText(((ViewGroup)v).getChildAt(i)));return s.toString();}
 void sample(String kind,long amount,String day,String person,String uuid,String loan){ContentValues v=new ContentValues();v.put("uuid",uuid);v.put("kind",kind);v.put("amount",amount);v.put("day",day);v.put("account","Cash");v.put("dest","");v.put("category",person.isEmpty()?"Food":"Debt");v.put("note","");v.put("person",person);v.put("loan",loan);activity.db.insertOrThrow("tx",null,v);}
