 @Test public void chartTouchAnnouncesExactCumulativeAndCategoryAmounts()throws Exception{LedgerChart line=new LedgerChart(activity,new long[]{125,275,50},new int[]{activity.ORANGE},false,2,activity.FG,activity.MUTED,activity.ORANGE,activity.CARD);line.interaction("Day",activity::ru,null,"Cumulative expenses");int width=activity.d(320),height=activity.d(180);line.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));line.layout(0,0,width,height);long time=android.os.SystemClock.uptimeMillis();assertTrue(line.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,width/2f,height/2f,0)));assertTrue(line.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time+10,android.view.MotionEvent.ACTION_UP,width/2f,height/2f,0)));assertTrue(line.getContentDescription().toString().contains("Day 2: "+activity.ru(400)));LedgerChart donut=new LedgerChart(activity,new long[]{100,300},new int[]{activity.ORANGE,activity.GREEN},true,2,activity.FG,activity.MUTED,activity.ORANGE,activity.CARD);donut.interaction("Day",activity::ru,new String[]{"Food","Rent"},"Category totals");width=activity.d(320);height=activity.d(220);donut.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));donut.layout(0,0,width,height);float density=activity.getResources().getDisplayMetrics().density;float radius=(Math.min(width,height)-20*density)/2-15*density;float x=width/2f,y=height/2f+radius;time=android.os.SystemClock.uptimeMillis();donut.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time,android.view.MotionEvent.ACTION_DOWN,x,y,0));donut.dispatchTouchEvent(android.view.MotionEvent.obtain(time,time+10,android.view.MotionEvent.ACTION_UP,x,y,0));assertTrue(donut.getContentDescription().toString().contains("Rent: "+activity.ru(300)));}
