 GlassDock findDock(View v){if(v instanceof GlassDock)return(GlassDock)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){GlassDock result=findDock(((ViewGroup)v).getChildAt(i));if(result!=null)return result;}return null;}
 @Test public void floatingDockAnimationHasIntermediateFrames()throws Exception{org.robolectric.shadows.ShadowChoreographer.setPaused(true);org.robolectric.shadows.ShadowChoreographer.setFrameDelay(java.time.Duration.ofMillis(16));org.robolectric.util.ReflectionHelpers.callStaticMethod(android.animation.ValueAnimator.class,"setDurationScale",org.robolectric.util.ReflectionHelpers.ClassParameter.from(float.class,1f));activity.savePreference("surface","Liquid Glass");activity.page="home";activity.render();org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(400));activity.previousNavIndex=0;activity.page="plan";activity.render();View view=activity.root;int w=1080,h=2400;view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);GlassDock dock=findDock(view);assertNotNull(dock);View nav=dock.getChildAt(1);assertEquals(5,((ViewGroup)nav).getChildCount());android.graphics.drawable.LayerDrawable layers=(android.graphics.drawable.LayerDrawable)nav.getBackground();GlassDock.PillSurface pill=(GlassDock.PillSurface)layers.getDrawable(1);float first=pill.value;boolean intermediate=false;for(int i=0;i<8;i++){org.robolectric.Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(40));float value=pill.value;if(value>0&&value<2)intermediate=true;dock.capture();Bitmap frame=Bitmap.createBitmap(1080,220,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(frame);canvas.drawColor(0xff071014);layers.setBounds(0,0,1080,220);layers.draw(canvas);try(FileOutputStream out=new FileOutputStream("/downloads/hisab-v2/qa/feedback-motion-"+i+".png")){frame.compress(Bitmap.CompressFormat.PNG,100,out);}frame.recycle();}assertEquals(0f,first,0.01f);assertTrue("Expected an intermediate pill position",intermediate);assertEquals(2f,pill.value,0.01f);}

